import { useState, useEffect, useMemo, useRef } from "react";
import { apiFetch, getUserName, signOut } from "./auth.js";

const MONTHS = ["Jan","Feb","Mar","Apr","May","Jun","Jul","Aug","Sep","Oct","Nov","Dec"];
const MONTH_FULL = {Jan:"January",Feb:"February",Mar:"March",Apr:"April",May:"May",Jun:"June",
  Jul:"July",Aug:"August",Sep:"September",Oct:"October",Nov:"November",Dec:"December"};
const NB_BLUE = "#1e85d0";
const APP_VERSION = "v2.1.1";
const NB_LOGO = "data:image/png;base64,";

export default function App() {
  const currentYear = new Date().getFullYear();
  const currentMonth = MONTHS[new Date().getMonth()];

  const [view, setView] = useState("entry");
  const [selectedYear, setSelectedYear] = useState(currentYear);
  const [selectedMonth, setSelectedMonth] = useState(currentMonth);
  const [showHelp, setShowHelp] = useState(false);

  const [yearCache, setYearCache] = useState({});
  const [loading, setLoading] = useState(false);
  const [error, setError] = useState(null);
  const [lockedMonths, setLockedMonths] = useState({});
  const loadingYears = useRef(new Set());

  const [form, setForm] = useState({name:"",outcome:"A",disposition:"CB",broker:"",ourCustomer:true});
  const [saving, setSaving] = useState(false);
  const [editingId, setEditingId] = useState(null);
  const [editForm, setEditForm] = useState({name:"",outcome:"A",disposition:"CB",broker:"",ourCustomer:true,date:""});

  async function loadYear(year) {
    if (yearCache[year] !== undefined || loadingYears.current.has(year)) return;
    loadingYears.current.add(year);
    setLoading(true);
    try {
      const res = await apiFetch(`/api/entries?year=${year}`);
      if (!res.ok) throw new Error(`HTTP ${res.status}`);
      const data = await res.json();
      setYearCache(prev => ({...prev, [year]: data}));
    } catch(e) { setError(e.message); }
    finally {
      loadingYears.current.delete(year);
      setLoading(false);
    }
  }

  async function loadLockedMonths() {
    try {
      const res = await apiFetch("/api/locked");
      if (!res.ok) return;
      const data = await res.json();
      const map = {};
      data.forEach(r => { if (r.is_unlocked) map[`${r.year}-${r.month}`] = true; });
      setLockedMonths(map);
    } catch(e) {}
  }

  useEffect(() => {
    loadYear(currentYear);
    loadLockedMonths();
  }, []);

  useEffect(() => {
    loadYear(selectedYear);
  }, [selectedYear]);

  const allMonthlyData = useMemo(() => {
    const map = {};
    Object.entries(yearCache).forEach(([, entries]) => {
      if (!entries) return;
      entries.forEach(e => {
        const key = `${e.year}-${e.month}`;
        if (!map[key]) map[key] = {year:e.year, month:e.month, entries:[]};
        map[key].entries.push(e);
      });
    });
    return map;
  }, [yearCache]);

  function countEntries(entries) {
    return {
      a: entries.filter(e=>e.outcome==="A").length,
      b: entries.filter(e=>e.outcome==="B").length,
      c: entries.filter(e=>e.outcome==="C").length,
      lbb: entries.filter(e=>e.disposition==="LBB").length,
      cb: entries.filter(e=>e.disposition==="CB").length,
      ground: entries.filter(e=>e.disposition==="Ground").length,
    };
  }

  function getMonthTotals(year, month) {
    const rec = allMonthlyData[`${year}-${month}`];
    return countEntries(rec ? rec.entries : []);
  }

  function getYearTotals(year) {
    let t = {a:0,b:0,c:0,lbb:0,cb:0,ground:0};
    MONTHS.forEach(mo => {
      const m = getMonthTotals(year, mo);
      t.a+=m.a; t.b+=m.b; t.c+=m.c; t.lbb+=m.lbb; t.cb+=m.cb; t.ground+=m.ground;
    });
    return t;
  }

  function isMonthLocked(year, month) {
    if (lockedMonths[`${year}-${month}`]) return false;
    const now = new Date();
    const lockDate = new Date(year, MONTHS.indexOf(month) + 2, 1);
    return now >= lockDate;
  }

  async function unlockMonth(year, month) {
    try {
      await apiFetch("/api/locked", {
        method:"POST",
        headers:{"Content-Type":"application/json"},
        body:JSON.stringify({year, month, is_unlocked:true}),
      });
      setLockedMonths(prev => ({...prev, [`${year}-${month}`]:true}));
    } catch(e) { setError(e.message); }
  }

  async function addEntry() {
    if (!form.name.trim() || isMonthLocked(selectedYear, selectedMonth)) return;
    setSaving(true);
    try {
      const res = await apiFetch("/api/entries", {
        method:"POST",
        headers:{"Content-Type":"application/json"},
        body:JSON.stringify({
          name:form.name.trim(), outcome:form.outcome, disposition:form.disposition,
          broker:form.broker.trim(), our_customer:form.ourCustomer,
          year:selectedYear, month:selectedMonth,
        }),
      });
      if (!res.ok) throw new Error(`HTTP ${res.status}`);
      const newEntry = await res.json();
      setYearCache(prev => ({...prev, [selectedYear]:[...(prev[selectedYear]||[]), newEntry]}));
      setForm({name:"",outcome:"A",disposition:"CB",broker:"",ourCustomer:true});
    } catch(e) { setError(e.message); }
    finally { setSaving(false); }
  }

  async function deleteEntry(id) {
    try {
      const res = await apiFetch(`/api/entries/${id}`, {method:"DELETE"});
      if (!res.ok) throw new Error(`HTTP ${res.status}`);
      setYearCache(prev => ({...prev, [selectedYear]:(prev[selectedYear]||[]).filter(e=>e.id!==id)}));
    } catch(e) { setError(e.message); }
  }

  function startEdit(entry) {
    setEditingId(entry.id);
    setEditForm({
      name:entry.name, outcome:entry.outcome,
      disposition:entry.disposition||"CB", broker:entry.broker||"",
      ourCustomer:entry.our_customer!==false,
      date:toInputDate(entry.timestamp||entry.created_at),
    });
  }

  async function saveEdit() {
    if (!editForm.name.trim() || !editForm.date) return;
    setSaving(true);
    try {
      const res = await apiFetch(`/api/entries/${editingId}`, {
        method:"PUT",
        headers:{"Content-Type":"application/json"},
        body:JSON.stringify({
          name:editForm.name.trim(), outcome:editForm.outcome,
          disposition:editForm.disposition, broker:editForm.broker.trim(),
          our_customer:editForm.ourCustomer, created_at:editForm.date,
        }),
      });
      if (!res.ok) throw new Error(`HTTP ${res.status}`);
      const updated = await res.json();
      setYearCache(prev => ({
        ...prev,
        [selectedYear]:(prev[selectedYear]||[]).map(e=>e.id===editingId?updated:e),
      }));
      setEditingId(null);
    } catch(e) { setError(e.message); }
    finally { setSaving(false); }
  }

  function cancelEdit() { setEditingId(null); }

  // created_at is stored as TIMESTAMPTZ (midnight UTC for picked dates). Read UTC
  // components so an entry dated 8/9 doesn't render as 8/8 in Eastern time.
  function formatDate(ts) {
    if (!ts) return "—";
    const d = new Date(ts);
    return `${d.getUTCMonth()+1}/${d.getUTCDate()}/${d.getUTCFullYear()}`;
  }

  function toInputDate(ts) {
    if (!ts) return "";
    const d = new Date(ts);
    return `${d.getUTCFullYear()}-${String(d.getUTCMonth()+1).padStart(2,"0")}-${String(d.getUTCDate()).padStart(2,"0")}`;
  }

  function handlePrint() { window.print(); }

  const currentEntries = useMemo(() => {
    const rec = allMonthlyData[`${selectedYear}-${selectedMonth}`];
    return rec ? rec.entries : [];
  }, [allMonthlyData, selectedYear, selectedMonth]);

  const currentTotals = useMemo(() => countEntries(currentEntries), [currentEntries]);
  const currentOurTotals = useMemo(() => countEntries(currentEntries.filter(e=>e.our_customer!==false)), [currentEntries]);

  const ytdData = useMemo(() => {
    const monthIndex = MONTHS.indexOf(selectedMonth);
    const entries = [];
    for (let i=0; i<=monthIndex; i++) {
      const rec = allMonthlyData[`${selectedYear}-${MONTHS[i]}`];
      if (rec) entries.push(...rec.entries);
    }
    return entries;
  }, [allMonthlyData, selectedYear, selectedMonth]);

  const ytd = useMemo(() => countEntries(ytdData), [ytdData]);
  const ytdOur = useMemo(() => countEntries(ytdData.filter(e=>e.our_customer!==false)), [ytdData]);

  const outcomeLabel = {A:"Renewed",B:"Returned",C:"Purchased"};
  const outcomeColor = {A:"#166534",B:"#991b1b",C:"#92400e"};
  const outcomeBg = {A:"#dcfce7",B:"#fee2e2",C:"#fef3c7"};
  const years = [];
  for (let y=2012; y<=2050; y++) years.push(y);

  return (
    <div style={{fontFamily:"'Segoe UI',system-ui,sans-serif",minHeight:"100vh",background:"linear-gradient(135deg, #1e85d0 0%, #0d5fa0 100%)",color:"#1e293b"}}>
      <style>{`
        @media print { .no-print { display:none!important; } body { background:white; } }
      `}</style>

      {error && (
        <div style={{background:"#fee2e2",borderBottom:"2px solid #ef4444",padding:"10px 24px",display:"flex",justifyContent:"space-between",alignItems:"center",fontSize:13,color:"#991b1b",fontWeight:600}}>
          <span>Error: {error}</span>
          <button onClick={()=>setError(null)} style={{background:"none",border:"none",color:"#991b1b",cursor:"pointer",fontSize:18,fontWeight:700,lineHeight:1}}>✕</button>
        </div>
      )}

      <header className="no-print" style={{background:"white",borderBottom:`3px solid ${NB_BLUE}`,padding:"0 24px",display:"flex",alignItems:"center",gap:16,boxShadow:"0 2px 8px rgba(0,0,0,0.08)"}}>
        <div style={{display:"flex",alignItems:"center",gap:12,padding:"12px 0"}}>
          <img src={NB_LOGO} alt="North Bay Cadillac GMC" style={{height:48,objectFit:"contain"}}/>
          <div style={{width:1,height:36,background:"#e2e8f0",margin:"0 4px"}}/>
          <div style={{fontWeight:700,fontSize:15,color:"#475569"}}>Lease Retention</div>
          <div style={{fontSize:10,fontWeight:600,color:"#94a3b8",marginLeft:8,paddingLeft:8,borderLeft:"1px solid #e2e8f0"}}>{APP_VERSION}</div>
        </div>
        <div style={{flex:1}}/>
        <nav style={{display:"flex",gap:4}}>
          {[["entry","Data Entry"],["report","Monthly Report"],["yearly","Year Summary"]].map(([v,label])=>(
            <button key={v} onClick={()=>setView(v)} style={{
              padding:"8px 16px",borderRadius:6,border:"none",cursor:"pointer",fontWeight:600,fontSize:13,
              background:view===v?NB_BLUE:"transparent",color:view===v?"white":"#475569",transition:"all 0.15s",
            }}>{label}</button>
          ))}
        </nav>
        <div style={{marginLeft:8,fontSize:12,color:"#94a3b8",fontWeight:600,letterSpacing:"0.5px"}}>{APP_VERSION}</div>
        <button onClick={()=>setShowHelp(true)} title="Help" style={{marginLeft:8,width:28,height:28,borderRadius:"50%",border:`1px solid ${NB_BLUE}`,background:"white",color:NB_BLUE,fontWeight:800,fontSize:14,cursor:"pointer",lineHeight:1}}>?</button>
        <span style={{marginLeft:8,display:"flex",alignItems:"center",gap:6,fontSize:13,color:"#111827",fontWeight:500}}>
          <svg width="16" height="16" viewBox="0 0 20 20" fill="#9ca3af" aria-hidden="true"><path fillRule="evenodd" d="M10 9a3 3 0 100-6 3 3 0 000 6zm-7 9a7 7 0 1114 0H3z" clipRule="evenodd"/></svg>
          {getUserName()}
        </span>
        <button onClick={signOut} style={{marginLeft:4,padding:"5px 12px",borderRadius:6,border:"1px solid #fca5a5",background:"#fee2e2",color:"#b91c1c",fontWeight:500,fontSize:13,cursor:"pointer",whiteSpace:"nowrap"}}>Sign out</button>
      </header>

      <div className="no-print" style={{background:"white",borderBottom:"1px solid #e2e8f0",padding:"10px 24px",display:"flex",alignItems:"center",gap:12,flexWrap:"wrap"}}>
        <span style={{fontSize:13,fontWeight:600,color:"#64748b",textTransform:"uppercase",letterSpacing:"0.5px"}}>Period</span>
        <select value={selectedMonth} onChange={e=>setSelectedMonth(e.target.value)}
          style={{padding:"6px 10px",border:`1px solid ${NB_BLUE}`,borderRadius:6,fontSize:14,fontWeight:600,color:NB_BLUE,background:"white",cursor:"pointer"}}>
          {MONTHS.map(m=><option key={m} value={m}>{MONTH_FULL[m]}</option>)}
        </select>
        <select value={selectedYear} onChange={e=>setSelectedYear(Number(e.target.value))}
          style={{padding:"6px 10px",border:`1px solid ${NB_BLUE}`,borderRadius:6,fontSize:14,fontWeight:600,color:NB_BLUE,background:"white",cursor:"pointer"}}>
          {years.map(y=><option key={y} value={y}>{y}</option>)}
        </select>
        <span style={{marginLeft:8,fontSize:14,color:"#94a3b8"}}>{MONTH_FULL[selectedMonth]} {selectedYear}</span>
        {loading && <span style={{marginLeft:8,fontSize:12,color:"#94a3b8",fontStyle:"italic"}}>Loading…</span>}
        <button
          onClick={()=>{setSelectedMonth(currentMonth);setSelectedYear(currentYear);}}
          disabled={selectedMonth===currentMonth&&selectedYear===currentYear}
          style={{marginLeft:12,padding:"6px 16px",background:(selectedMonth===currentMonth&&selectedYear===currentYear)?"#cbd5e1":NB_BLUE,color:"white",border:"none",borderRadius:6,fontSize:13,fontWeight:700,cursor:(selectedMonth===currentMonth&&selectedYear===currentYear)?"default":"pointer",transition:"background 0.15s"}}>
          ← This Month
        </button>
      </div>

      <main style={{maxWidth:1000,margin:"0 auto",padding:"24px 16px"}}>

        {view==="entry" && (
          <div>
            <div className="no-print" style={{background:"white",borderRadius:10,border:"1px solid #38bdf8",borderTop:`3px solid ${NB_BLUE}`,padding:24,marginBottom:24,boxShadow:"0 1px 4px rgba(0,0,0,0.06)"}}>
              <h2 style={{margin:"0 0 18px",fontSize:16,fontWeight:700,color:"#1e293b"}}>
                Add Customer – {MONTH_FULL[selectedMonth]} {selectedYear}
              </h2>
              {isMonthLocked(selectedYear, selectedMonth) && (
                <div style={{background:"#fee2e2",border:"1px solid #fca5a5",borderRadius:6,padding:"10px 14px",marginBottom:16,fontSize:13,color:"#991b1b",fontWeight:600,display:"flex",alignItems:"center",justifyContent:"space-between",gap:12}}>
                  <span>🔒 This month is locked – {MONTH_FULL[selectedMonth]} {selectedYear} was locked 60 days after the end of the month.</span>
                  <button onClick={()=>unlockMonth(selectedYear,selectedMonth)} style={{flexShrink:0,padding:"5px 14px",background:"#991b1b",color:"white",border:"none",borderRadius:5,fontWeight:700,fontSize:12,cursor:"pointer"}}>Unlock</button>
                </div>
              )}
              <div style={{display:"grid",gridTemplateColumns:"1fr 1fr 1fr",gap:12,marginBottom:12}}>
                <div>
                  <label style={{display:"block",fontSize:12,fontWeight:600,color:"#64748b",marginBottom:4,textTransform:"uppercase",letterSpacing:"0.5px"}}>Customer Name *</label>
                  <input value={form.name} onChange={e=>setForm(f=>({...f,name:e.target.value}))}
                    onKeyDown={e=>e.key==="Enter"&&addEntry()}
                    placeholder="Enter name..."
                    style={{width:"100%",padding:"8px 10px",border:"1px solid #cbd5e1",borderRadius:6,fontSize:14,boxSizing:"border-box"}}/>
                </div>
                <div>
                  <label style={{display:"block",fontSize:12,fontWeight:600,color:"#64748b",marginBottom:4,textTransform:"uppercase",letterSpacing:"0.5px"}}>Outcome</label>
                  <select value={form.outcome} onChange={e=>setForm(f=>({...f,outcome:e.target.value}))}
                    style={{width:"100%",padding:"8px 10px",border:"1px solid #cbd5e1",borderRadius:6,fontSize:14}}>
                    <option value="A">Lease Renewed</option>
                    <option value="B">Only Returned</option>
                    <option value="C">Purchased Old Lease</option>
                  </select>
                </div>
                <div>
                  <label style={{display:"block",fontSize:12,fontWeight:600,color:"#64748b",marginBottom:4,textTransform:"uppercase",letterSpacing:"0.5px"}}>Disposition</label>
                  <select value={form.disposition} onChange={e=>setForm(f=>({...f,disposition:e.target.value}))}
                    style={{width:"100%",padding:"8px 10px",border:"1px solid #cbd5e1",borderRadius:6,fontSize:14}}>
                    <option value="CB">CB</option>
                    <option value="LBB">LBB – Lease Buy Back</option>
                    <option value="Ground">Ground</option>
                  </select>
                </div>
              </div>
              <div style={{display:"flex",gap:12,alignItems:"flex-end",flexWrap:"wrap"}}>
                <div style={{flex:1,minWidth:160}}>
                  <label style={{display:"block",fontSize:12,fontWeight:600,color:"#64748b",marginBottom:4,textTransform:"uppercase",letterSpacing:"0.5px"}}>Broker / Salesperson (optional)</label>
                  <input value={form.broker} onChange={e=>setForm(f=>({...f,broker:e.target.value}))}
                    placeholder="e.g. JG, JY Broker..."
                    style={{width:"100%",padding:"8px 10px",border:"1px solid #cbd5e1",borderRadius:6,fontSize:14,boxSizing:"border-box"}}/>
                </div>
                <div style={{display:"flex",alignItems:"center",gap:8,paddingBottom:2}}>
                  <input type="checkbox" id="ourCust" checked={form.ourCustomer}
                    onChange={e=>setForm(f=>({...f,ourCustomer:e.target.checked}))}
                    style={{width:16,height:16,cursor:"pointer",accentColor:NB_BLUE}}/>
                  <label htmlFor="ourCust" style={{fontSize:13,fontWeight:600,color:"#374151",cursor:"pointer",userSelect:"none",whiteSpace:"nowrap"}}>Our Customer</label>
                </div>
                <button onClick={addEntry} disabled={!form.name.trim()||isMonthLocked(selectedYear,selectedMonth)}
                  style={{padding:"9px 24px",background:(form.name.trim()&&!isMonthLocked(selectedYear,selectedMonth))?NB_BLUE:"#94a3b8",color:"white",border:"none",borderRadius:6,fontSize:14,fontWeight:700,cursor:(form.name.trim()&&!isMonthLocked(selectedYear,selectedMonth))?"pointer":"not-allowed",transition:"background 0.15s"}}>
                  {saving?<span>Adding…</span>:"+ Add Entry"}
                </button>
              </div>
            </div>

            <TotalsCard totals={currentTotals} ourTotals={currentOurTotals} label={`MTD – ${MONTH_FULL[selectedMonth]} ${selectedYear}`} showDisp={selectedYear>=2021}/>
            <div style={{marginTop:16}}>
              <TotalsCard totals={ytd} ourTotals={ytdOur} label={`YTD – Through ${MONTH_FULL[selectedMonth]} ${selectedYear}`} showDisp={selectedYear>=2021}/>
            </div>

            {currentEntries.length > 0 && (
              <div className="no-print" style={{background:"white",borderRadius:10,border:"1px solid #38bdf8",overflow:"hidden",marginTop:20}}>
                <div style={{padding:"14px 20px",borderBottom:"1px solid #f1f5f9",display:"flex",justifyContent:"space-between",alignItems:"center"}}>
                  <span style={{fontWeight:700,fontSize:15}}>Entries – {MONTH_FULL[selectedMonth]} {selectedYear}</span>
                  <span style={{fontSize:13,color:"#64748b"}}>{currentEntries.length} entries this month</span>
                </div>
                <table style={{width:"100%",borderCollapse:"collapse"}}>
                  <thead>
                    <tr style={{background:"#f8fafc"}}>
                      {["Date","Customer","Outcome","Disposition","Broker","Our Cust.",""].map(h=>(
                        <th key={h} style={{padding:"10px 16px",textAlign:"left",fontSize:12,fontWeight:600,color:"#64748b",textTransform:"uppercase",letterSpacing:"0.5px"}}>{h}</th>
                      ))}
                    </tr>
                  </thead>
                  <tbody>
                    {currentEntries.map((e,i)=>{
                      const canEdit = !e.is_historical && !isMonthLocked(selectedYear, selectedMonth);
                      if (editingId === e.id) {
                        return (
                          <tr key={e.id} style={{borderTop:"1px solid #38bdf8",background:"#f0f9ff"}}>
                            <td style={{padding:"6px 10px"}}>
                              <input type="date" value={editForm.date} onChange={ev=>setEditForm(f=>({...f,date:ev.target.value}))}
                                style={{padding:"4px",border:"1px solid #38bdf8",borderRadius:4,fontSize:12}}/>
                            </td>
                            <td style={{padding:"6px 10px"}}>
                              <input value={editForm.name} onChange={ev=>setEditForm(f=>({...f,name:ev.target.value}))}
                                style={{width:"100%",padding:"4px 8px",border:"1px solid #38bdf8",borderRadius:4,fontSize:13,boxSizing:"border-box"}}/>
                            </td>
                            <td style={{padding:"6px 10px"}}>
                              <select value={editForm.outcome} onChange={ev=>setEditForm(f=>({...f,outcome:ev.target.value}))}
                                style={{padding:"4px",border:"1px solid #38bdf8",borderRadius:4,fontSize:13}}>
                                <option value="A">Renewed</option>
                                <option value="B">Returned</option>
                                <option value="C">Purchased</option>
                              </select>
                            </td>
                            <td style={{padding:"6px 10px"}}>
                              <select value={editForm.disposition} onChange={ev=>setEditForm(f=>({...f,disposition:ev.target.value}))}
                                style={{padding:"4px",border:"1px solid #38bdf8",borderRadius:4,fontSize:13}}>
                                <option value="CB">CB</option>
                                <option value="LBB">LBB</option>
                                <option value="Ground">Ground</option>
                              </select>
                            </td>
                            <td style={{padding:"6px 10px"}}>
                              <input value={editForm.broker} onChange={ev=>setEditForm(f=>({...f,broker:ev.target.value}))}
                                style={{width:"100%",padding:"4px 8px",border:"1px solid #38bdf8",borderRadius:4,fontSize:13,boxSizing:"border-box"}}/>
                            </td>
                            <td style={{padding:"6px 10px",textAlign:"center"}}>
                              <input type="checkbox" checked={editForm.ourCustomer}
                                onChange={ev=>setEditForm(f=>({...f,ourCustomer:ev.target.checked}))}
                                style={{width:16,height:16,cursor:"pointer",accentColor:NB_BLUE}}/>
                            </td>
                            <td style={{padding:"6px 10px",whiteSpace:"nowrap"}}>
                              <button onClick={saveEdit} style={{background:NB_BLUE,color:"white",border:"none",borderRadius:4,padding:"4px 12px",fontSize:12,fontWeight:700,cursor:"pointer",marginRight:4}}>Save</button>
                              <button onClick={cancelEdit} style={{background:"none",border:"1px solid #cbd5e1",borderRadius:4,padding:"4px 10px",fontSize:12,cursor:"pointer",color:"#64748b"}}>✕</button>
                            </td>
                          </tr>
                        );
                      }
                      return (
                        <tr key={e.id} style={{borderTop:"1px solid #f1f5f9",background:i%2===0?"white":"#fafafa"}}>
                          <td style={{padding:"10px 16px",fontSize:12,color:"#94a3b8"}}>{formatDate(e.timestamp||e.created_at)}</td>
                          <td style={{padding:"10px 16px",fontWeight:500}}>{e.name}</td>
                          <td style={{padding:"10px 16px"}}>
                            <span style={{display:"inline-block",padding:"2px 10px",borderRadius:20,fontSize:12,fontWeight:600,background:outcomeBg[e.outcome],color:outcomeColor[e.outcome]}}>
                              {outcomeLabel[e.outcome]}
                            </span>
                          </td>
                          <td style={{padding:"10px 16px",fontSize:13,color:"#475569"}}>{e.disposition||"—"}</td>
                          <td style={{padding:"10px 16px",fontSize:13,color:"#64748b"}}>{e.broker||"—"}</td>
                          <td style={{padding:"10px 16px",textAlign:"center",fontSize:14}}>
                            {e.our_customer!==false
                              ? <span style={{color:"#166534",fontWeight:700}}>✓</span>
                              : <span style={{color:"#94a3b8"}}>—</span>}
                          </td>
                          <td style={{padding:"10px 16px",display:"flex",gap:6,alignItems:"center"}}>
                            {canEdit && <button onClick={()=>startEdit(e)} title="Edit" style={{background:"none",border:`1px solid ${NB_BLUE}`,color:NB_BLUE,cursor:"pointer",fontSize:13,borderRadius:4,padding:"2px 8px",fontWeight:600,lineHeight:1}}>✎</button>}
                            {canEdit && <button onClick={()=>deleteEntry(e.id)} title="Delete" style={{background:"none",border:"none",color:"#ef4444",cursor:"pointer",fontSize:18,lineHeight:1}}>✕</button>}
                          </td>
                        </tr>
                      );
                    })}
                  </tbody>
                </table>
              </div>
            )}
          </div>
        )}

        {view==="report" && (
          <div>
            <div className="no-print" style={{display:"flex",justifyContent:"flex-end",marginBottom:16}}>
              <button onClick={handlePrint} style={{padding:"8px 20px",background:NB_BLUE,color:"white",border:"none",borderRadius:6,fontWeight:600,cursor:"pointer",fontSize:14}}>
                Print / Save PDF
              </button>
            </div>
            <div style={{background:"white",borderRadius:10,border:"1px solid #38bdf8",padding:32,boxShadow:"0 1px 4px rgba(0,0,0,0.06)"}}>
              <div style={{display:"flex",justifyContent:"space-between",alignItems:"flex-start",marginBottom:24,paddingBottom:16,borderBottom:`2px solid ${NB_BLUE}`}}>
                <img src={NB_LOGO} alt="North Bay Cadillac GMC" style={{height:40,objectFit:"contain"}}/>
                <div style={{textAlign:"right"}}>
                  <div style={{fontSize:20,fontWeight:800,color:NB_BLUE}}>{MONTH_FULL[selectedMonth]} {selectedYear}</div>
                  <div style={{fontSize:12,color:"#94a3b8"}}>Printed {new Date().toLocaleDateString()}</div>
                </div>
              </div>

              <ReportTotalsTable label={`Current Month – ${MONTH_FULL[selectedMonth]} ${selectedYear}`} totals={currentTotals} ourTotals={currentOurTotals} showDisp={selectedYear>=2021}/>
              <div style={{marginTop:20}}>
                <ReportTotalsTable label={`Year-to-Date – Through ${MONTH_FULL[selectedMonth]} ${selectedYear}`} totals={ytd} ourTotals={ytdOur} showDisp={selectedYear>=2021}/>
              </div>

              {currentEntries.length > 0 && (
                <div style={{marginTop:24}}>
                  <div style={{fontWeight:700,fontSize:14,color:"#475569",marginBottom:10,textTransform:"uppercase",letterSpacing:"0.5px"}}>Customer Entries</div>
                  <table style={{width:"100%",borderCollapse:"collapse",fontSize:13}}>
                    <thead>
                      <tr style={{background:"#f8fafc"}}>
                        {["#","Date","Customer","Outcome","Disposition","Broker","Our Cust."].map(h=>(
                          <th key={h} style={{padding:"8px 12px",textAlign:"left",fontWeight:600,color:"#64748b",borderBottom:"1px solid #e2e8f0"}}>{h}</th>
                        ))}
                      </tr>
                    </thead>
                    <tbody>
                      {currentEntries.map((e,i)=>(
                        <tr key={e.id} style={{borderBottom:"1px solid #f1f5f9"}}>
                          <td style={{padding:"7px 12px",color:"#94a3b8"}}>{i+1}</td>
                          <td style={{padding:"7px 12px",color:"#94a3b8",fontSize:12}}>{formatDate(e.timestamp||e.created_at)}</td>
                          <td style={{padding:"7px 12px",fontWeight:500}}>{e.name}</td>
                          <td style={{padding:"7px 12px"}}>
                            <span style={{padding:"1px 8px",borderRadius:12,fontSize:11,fontWeight:700,background:outcomeBg[e.outcome],color:outcomeColor[e.outcome]}}>
                              {outcomeLabel[e.outcome]}
                            </span>
                          </td>
                          <td style={{padding:"7px 12px",color:"#475569"}}>{e.disposition||"—"}</td>
                          <td style={{padding:"7px 12px",color:"#64748b"}}>{e.broker||"—"}</td>
                          <td style={{padding:"7px 12px",textAlign:"center"}}>
                            {e.our_customer!==false?<span style={{color:"#166534",fontWeight:700}}>✓</span>:"—"}
                          </td>
                        </tr>
                      ))}
                    </tbody>
                  </table>
                </div>
              )}
            </div>
          </div>
        )}

        {view==="yearly" && (
          <div>
            <div className="no-print" style={{display:"flex",justifyContent:"flex-end",marginBottom:16}}>
              <button onClick={handlePrint} style={{padding:"8px 20px",background:NB_BLUE,color:"white",border:"none",borderRadius:6,fontWeight:600,cursor:"pointer",fontSize:14}}>
                Print / Save PDF
              </button>
            </div>
            <div style={{background:"white",borderRadius:10,border:"1px solid #38bdf8",overflow:"hidden",boxShadow:"0 1px 4px rgba(0,0,0,0.06)"}}>
              <div style={{padding:"20px 24px",borderBottom:`2px solid ${NB_BLUE}`,display:"flex",justifyContent:"space-between",alignItems:"center"}}>
                <div>
                  <div style={{fontWeight:800,fontSize:18,color:"#1e293b"}}>Annual Summary – {selectedYear}</div>
                  <div style={{fontSize:13,color:"#64748b"}}>North Bay Cadillac \xb7 GMC Lease Retention</div>
                </div>
                <div style={{fontSize:12,color:"#94a3b8"}}>Printed {new Date().toLocaleDateString()}</div>
              </div>
              <div style={{overflowX:"auto"}}>
                <table style={{width:"100%",borderCollapse:"collapse",fontSize:13}}>
                  <thead>
                    <tr style={{background:"#f8fafc"}}>
                      <th style={{padding:"10px 16px",textAlign:"left",fontWeight:600,color:"#64748b",borderBottom:"1px solid #e2e8f0"}}>Month</th>
                      <th style={{padding:"10px 16px",textAlign:"center",fontWeight:600,color:"#166534",borderBottom:"1px solid #e2e8f0"}}>Renewed</th>
                      <th style={{padding:"10px 16px",textAlign:"center",fontWeight:600,color:"#991b1b",borderBottom:"1px solid #e2e8f0"}}>Returned</th>
                      <th style={{padding:"10px 16px",textAlign:"center",fontWeight:600,color:"#92400e",borderBottom:"1px solid #e2e8f0"}}>Purchased</th>
                      {selectedYear>=2021 && <>
                        <th style={{padding:"10px 16px",textAlign:"center",fontWeight:600,color:"#64748b",borderBottom:"1px solid #e2e8f0"}}>LBB</th>
                        <th style={{padding:"10px 16px",textAlign:"center",fontWeight:600,color:"#64748b",borderBottom:"1px solid #e2e8f0"}}>CB</th>
                        <th style={{padding:"10px 16px",textAlign:"center",fontWeight:600,color:"#64748b",borderBottom:"1px solid #e2e8f0"}}>Ground</th>
                      </>}
                      <th style={{padding:"10px 16px",textAlign:"center",fontWeight:600,color:"#1e293b",borderBottom:"1px solid #e2e8f0"}}>Total</th>
                    </tr>
                  </thead>
                  <tbody>
                    {MONTHS.map((mo,i)=>{
                      const t = getMonthTotals(selectedYear, mo);
                      const total = t.a+t.b+t.c;
                      const hasData = total > 0;
                      return (
                        <tr key={mo} style={{borderBottom:"1px solid #f1f5f9",background:i%2===0?"white":"#fafafa",opacity:hasData?1:0.4}}>
                          <td style={{padding:"10px 16px",fontWeight:600}}>{MONTH_FULL[mo]}</td>
                          <td style={{padding:"10px 16px",textAlign:"center",color:"#166534",fontWeight:700}}>{hasData?t.a:"—"}</td>
                          <td style={{padding:"10px 16px",textAlign:"center",color:"#991b1b",fontWeight:700}}>{hasData?t.b:"—"}</td>
                          <td style={{padding:"10px 16px",textAlign:"center",color:"#92400e",fontWeight:700}}>{hasData?t.c:"—"}</td>
                          {selectedYear>=2021 && <>
                            <td style={{padding:"10px 16px",textAlign:"center",color:"#475569"}}>{hasData?(t.lbb||"—"):"—"}</td>
                            <td style={{padding:"10px 16px",textAlign:"center",color:"#475569"}}>{hasData?(t.cb||"—"):"—"}</td>
                            <td style={{padding:"10px 16px",textAlign:"center",color:"#475569"}}>{hasData?(t.ground||"—"):"—"}</td>
                          </>}
                          <td style={{padding:"10px 16px",textAlign:"center",fontWeight:700,color:NB_BLUE}}>{hasData?total:"—"}</td>
                        </tr>
                      );
                    })}
                    {(()=>{
                      const yt = getYearTotals(selectedYear);
                      const total = yt.a+yt.b+yt.c;
                      return (
                        <tr style={{background:NB_BLUE,color:"white"}}>
                          <td style={{padding:"12px 16px",fontWeight:800,fontSize:14}}>YEAR TOTAL</td>
                          <td style={{padding:"12px 16px",textAlign:"center",fontWeight:800,fontSize:14}}>{yt.a}</td>
                          <td style={{padding:"12px 16px",textAlign:"center",fontWeight:800,fontSize:14}}>{yt.b}</td>
                          <td style={{padding:"12px 16px",textAlign:"center",fontWeight:800,fontSize:14}}>{yt.c}</td>
                          {selectedYear>=2021 && <>
                            <td style={{padding:"12px 16px",textAlign:"center",fontWeight:800,fontSize:14}}>{yt.lbb||0}</td>
                            <td style={{padding:"12px 16px",textAlign:"center",fontWeight:800,fontSize:14}}>{yt.cb||0}</td>
                            <td style={{padding:"12px 16px",textAlign:"center",fontWeight:800,fontSize:14}}>{yt.ground||0}</td>
                          </>}
                          <td style={{padding:"12px 16px",textAlign:"center",fontWeight:800,fontSize:14}}>{total}</td>
                        </tr>
                      );
                    })()}
                  </tbody>
                </table>
              </div>
            </div>
          </div>
        )}
      </main>

      {showHelp && (
        <div onClick={()=>setShowHelp(false)} style={{position:"fixed",inset:0,background:"rgba(0,0,0,0.45)",zIndex:1000,display:"flex",alignItems:"center",justifyContent:"center"}}>
          <div onClick={e=>e.stopPropagation()} style={{background:"white",borderRadius:12,width:"100%",maxWidth:520,padding:32,boxShadow:"0 8px 32px rgba(0,0,0,0.18)",position:"relative",maxHeight:"90vh",overflowY:"auto"}}>
            <button onClick={()=>setShowHelp(false)} style={{position:"absolute",top:14,right:16,background:"none",border:"none",fontSize:20,cursor:"pointer",color:"#94a3b8",lineHeight:1}}>✕</button>
            <div style={{fontWeight:800,fontSize:18,color:"#1e293b",marginBottom:20}}>Quick Reference</div>
            <div style={{marginBottom:18}}>
              <div style={{fontWeight:700,fontSize:13,color:NB_BLUE,textTransform:"uppercase",letterSpacing:"0.5px",marginBottom:8}}>Outcomes</div>
              <div style={{display:"flex",flexDirection:"column",gap:6}}>
                {[["Renewed","#dcfce7","#166534","Customer leased again – retained"],["Returned","#fee2e2","#991b1b","Lease returned, did not buy or re-lease"],["Purchased","#fef3c7","#92400e","Customer bought their leased vehicle"]].map(([lbl,bg,color,desc])=>(
                  <div key={lbl} style={{display:"flex",alignItems:"center",gap:10}}>
                    <span style={{display:"inline-block",padding:"2px 12px",borderRadius:20,fontSize:12,fontWeight:700,background:bg,color,minWidth:80,textAlign:"center"}}>{lbl}</span>
                    <span style={{fontSize:13,color:"#475569"}}>{desc}</span>
                  </div>
                ))}
              </div>
            </div>
            <div style={{marginBottom:18}}>
              <div style={{fontWeight:700,fontSize:13,color:NB_BLUE,textTransform:"uppercase",letterSpacing:"0.5px",marginBottom:8}}>Dispositions</div>
              <div style={{display:"flex",flexDirection:"column",gap:6,fontSize:13,color:"#475569"}}>
                <div><span style={{fontWeight:700,color:"#1e293b"}}>CB</span> – Customer Buy: customer purchased the vehicle outright</div>
                <div><span style={{fontWeight:700,color:"#1e293b"}}>LBB</span> – Lease Buy Back: dealership bought back the lease</div>
                <div><span style={{fontWeight:700,color:"#1e293b"}}>Ground</span> – Vehicle was grounded / turned in to the bank</div>
              </div>
            </div>
            <div style={{marginBottom:18}}>
              <div style={{fontWeight:700,fontSize:13,color:NB_BLUE,textTransform:"uppercase",letterSpacing:"0.5px",marginBottom:8}}>Our Customer</div>
              <div style={{fontSize:13,color:"#475569"}}>Check "Our Customer" when the customer leased from North Bay (not via a broker). Tally cards show all customers and a separate "Our Customers" row.</div>
            </div>
            <div style={{marginBottom:18}}>
              <div style={{fontWeight:700,fontSize:13,color:NB_BLUE,textTransform:"uppercase",letterSpacing:"0.5px",marginBottom:8}}>Month Locking</div>
              <div style={{fontSize:13,color:"#475569"}}>Months lock 60 days after they end. Use <span style={{fontWeight:700,color:"#991b1b"}}>Unlock</span> to re-open for editing. Unlocks are saved permanently.</div>
            </div>
            <div>
              <div style={{fontWeight:700,fontSize:13,color:NB_BLUE,textTransform:"uppercase",letterSpacing:"0.5px",marginBottom:8}}>Dispositions shown from 2021 onward</div>
              <div style={{fontSize:13,color:"#475569"}}>LBB / CB / Ground columns appear only for years 2021+, when that tracking began.</div>
            </div>
          </div>
        </div>
      )}
    </div>
  );
}

function TotalsCard({totals, ourTotals, label, showDisp}) {
  const total = totals.a + totals.b + totals.c;
  const ourTotal = ourTotals ? ourTotals.a + ourTotals.b + ourTotals.c : null;
  return (
    <div style={{background:"white",borderRadius:10,border:"1px solid #38bdf8",padding:20,boxShadow:"0 1px 4px rgba(0,0,0,0.06)"}}>
      <div style={{fontWeight:700,fontSize:14,color:"#64748b",marginBottom:10,textTransform:"uppercase",letterSpacing:"0.5px"}}>{label}</div>
      <div style={{fontSize:10,fontWeight:700,color:"#94a3b8",textTransform:"uppercase",letterSpacing:"0.5px",marginBottom:8}}>All Customers</div>
      <div style={{display:"grid",gridTemplateColumns:`repeat(${showDisp?6:3},1fr)`,gap:12}}>
        <StatBox value={totals.a} label="Renewed" color="#166534" bg="#dcfce7" percent={total > 0 ? Math.round(totals.a/total*100) : 0}/>
        <StatBox value={totals.b} label="Returned" color="#991b1b" bg="#fee2e2" percent={total > 0 ? Math.round(totals.b/total*100) : 0}/>
        <StatBox value={totals.c} label="Purchased" color="#92400e" bg="#fef3c7" percent={total > 0 ? Math.round(totals.c/total*100) : 0}/>
        {showDisp && <>
          <StatBox value={totals.lbb||0} label="LBB" color="#1e40af" bg="#dbeafe"/>
          <StatBox value={totals.cb||0} label="CB" color="#5b21b6" bg="#ede9fe"/>
          <StatBox value={totals.ground||0} label="Ground" color="#475569" bg="#f1f5f9"/>
        </>}
      </div>
      <div style={{marginTop:8,paddingTop:8,borderTop:"1px solid #f1f5f9",display:"flex",gap:8,alignItems:"center"}}>
        <span style={{fontSize:12,color:"#94a3b8"}}>Total:</span>
        <span style={{fontSize:18,fontWeight:800,color:"#1e293b"}}>{total}</span>
      </div>
      {ourTotals && ourTotal!==null && (
        <>
          <div style={{borderTop:"1px dashed #bae6fd",margin:"14px 0 8px",fontSize:10,fontWeight:700,color:"#0369a1",textTransform:"uppercase",letterSpacing:"0.5px"}}>Our Customers</div>
          <div style={{display:"grid",gridTemplateColumns:`repeat(${showDisp?6:3},1fr)`,gap:12}}>
            <StatBox value={ourTotals.a} label="Renewed" color="#166534" bg="#dcfce7" percent={ourTotal > 0 ? Math.round(ourTotals.a/ourTotal*100) : 0}/>
            <StatBox value={ourTotals.b} label="Returned" color="#991b1b" bg="#fee2e2" percent={ourTotal > 0 ? Math.round(ourTotals.b/ourTotal*100) : 0}/>
            <StatBox value={ourTotals.c} label="Purchased" color="#92400e" bg="#fef3c7" percent={ourTotal > 0 ? Math.round(ourTotals.c/ourTotal*100) : 0}/>
            {showDisp && <>
              <StatBox value={ourTotals.lbb||0} label="LBB" color="#1e40af" bg="#dbeafe"/>
              <StatBox value={ourTotals.cb||0} label="CB" color="#5b21b6" bg="#ede9fe"/>
              <StatBox value={ourTotals.ground||0} label="Ground" color="#475569" bg="#f1f5f9"/>
            </>}
          </div>
          <div style={{marginTop:8,paddingTop:8,borderTop:"1px solid #f1f5f9",display:"flex",gap:8,alignItems:"center"}}>
            <span style={{fontSize:12,color:"#0369a1"}}>Our Total:</span>
            <span style={{fontSize:18,fontWeight:800,color:"#0369a1"}}>{ourTotal}</span>
          </div>
        </>
      )}
    </div>
  );
}

function StatBox({value, label, color, bg, percent}) {
  return (
    <div style={{background:bg,borderRadius:8,padding:"12px 14px",textAlign:"center"}}>
      <div style={{fontSize:26,fontWeight:800,color,lineHeight:1}}>{value}</div>
      <div style={{fontSize:11,fontWeight:600,color,marginTop:4,textTransform:"uppercase",letterSpacing:"0.5px"}}>{label}</div>
      {percent !== undefined && <div style={{fontSize:13,fontWeight:800,color,marginTop:6}}>{percent}%</div>}
    </div>
  );
}

function ReportTotalsTable({label, totals, ourTotals, showDisp}) {
  const total = totals.a+totals.b+totals.c;
  const ourTotal = ourTotals ? ourTotals.a+ourTotals.b+ourTotals.c : null;
  return (
    <div>
      <div style={{fontWeight:700,fontSize:13,color:"#64748b",marginBottom:8,textTransform:"uppercase",letterSpacing:"0.5px"}}>{label}</div>
      <table style={{width:"100%",borderCollapse:"collapse",fontSize:13,border:"1px solid #38bdf8",borderRadius:8,overflow:"hidden"}}>
        <thead>
          <tr style={{background:"#f8fafc"}}>
            <th style={{padding:"8px 14px",textAlign:"left",fontWeight:600,color:"#64748b",borderBottom:"1px solid #e2e8f0",width:50}}></th>
            <th style={{padding:"8px 14px",textAlign:"left",fontWeight:600,color:"#64748b",borderBottom:"1px solid #e2e8f0"}}>Renewed</th>
            <th style={{padding:"8px 14px",textAlign:"left",fontWeight:600,color:"#64748b",borderBottom:"1px solid #e2e8f0"}}>Returned</th>
            <th style={{padding:"8px 14px",textAlign:"left",fontWeight:600,color:"#64748b",borderBottom:"1px solid #e2e8f0"}}>Purchased</th>
            {showDisp && <>
              <th style={{padding:"8px 14px",textAlign:"left",fontWeight:600,color:"#64748b",borderBottom:"1px solid #e2e8f0"}}>LBB</th>
              <th style={{padding:"8px 14px",textAlign:"left",fontWeight:600,color:"#64748b",borderBottom:"1px solid #e2e8f0"}}>CB</th>
              <th style={{padding:"8px 14px",textAlign:"left",fontWeight:600,color:"#64748b",borderBottom:"1px solid #e2e8f0"}}>Ground</th>
            </>}
            <th style={{padding:"8px 14px",textAlign:"left",fontWeight:600,color:"#64748b",borderBottom:"1px solid #e2e8f0"}}>Total</th>
          </tr>
        </thead>
        <tbody>
          <tr>
            <td style={{padding:"8px 14px",fontWeight:700,color:"#64748b",fontSize:11,textTransform:"uppercase",letterSpacing:"0.5px"}}>All</td>
            <td style={{padding:"8px 14px",fontWeight:700,color:"#166534",fontSize:16}}>{totals.a}</td>
            <td style={{padding:"8px 14px",fontWeight:700,color:"#991b1b",fontSize:16}}>{totals.b}</td>
            <td style={{padding:"8px 14px",fontWeight:700,color:"#92400e",fontSize:16}}>{totals.c}</td>
            {showDisp && <>
              <td style={{padding:"8px 14px",fontWeight:600,color:"#1e40af"}}>{totals.lbb||0}</td>
              <td style={{padding:"8px 14px",fontWeight:600,color:"#5b21b6"}}>{totals.cb||0}</td>
              <td style={{padding:"8px 14px",fontWeight:600,color:"#475569"}}>{totals.ground||0}</td>
            </>}
            <td style={{padding:"8px 14px",fontWeight:800,color:"#1e293b",fontSize:16}}>{total}</td>
          </tr>
          {ourTotals && ourTotal!==null && (
            <tr style={{borderTop:"1px dashed #bae6fd",background:"#f0f9ff"}}>
              <td style={{padding:"8px 14px",fontWeight:700,color:"#0369a1",fontSize:11,textTransform:"uppercase",letterSpacing:"0.5px"}}>Ours</td>
              <td style={{padding:"8px 14px",fontWeight:700,color:"#166534",fontSize:16}}>{ourTotals.a}</td>
              <td style={{padding:"8px 14px",fontWeight:700,color:"#991b1b",fontSize:16}}>{ourTotals.b}</td>
              <td style={{padding:"8px 14px",fontWeight:700,color:"#92400e",fontSize:16}}>{ourTotals.c}</td>
              {showDisp && <>
                <td style={{padding:"8px 14px",fontWeight:600,color:"#1e40af"}}>{ourTotals.lbb||0}</td>
                <td style={{padding:"8px 14px",fontWeight:600,color:"#5b21b6"}}>{ourTotals.cb||0}</td>
                <td style={{padding:"8px 14px",fontWeight:600,color:"#475569"}}>{ourTotals.ground||0}</td>
              </>}
              <td style={{padding:"8px 14px",fontWeight:800,color:"#0369a1",fontSize:16}}>{ourTotal}</td>
            </tr>
          )}
        </tbody>
      </table>
    </div>
  );
}
